import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";import"./chunks/assets.BYG73sIP.js";var i=JSON.parse(`{"title":"Amazon Linux 2를 VirtualBox에서 실행하기","description":"","frontmatter":{"title":"Amazon Linux 2를 VirtualBox에서 실행하기","date":"2023-10-04T22:00+0900","tags":["AL2","Oracle VirtualBox"]},"headers":[],"relativePath":"posts/amazonlinux2-virtualbox.md","filePath":"posts/amazonlinux2-virtualbox.md","lastUpdated":1787309558000}`),a={name:`posts/amazonlinux2-virtualbox.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<p><a href="https://docs.aws.amazon.com/ko_kr/AWSEC2/latest/UserGuide/amazon-linux-2-virtual-machine.html" target="_blank" rel="noreferrer">Amazon Linux 2를 온프레미스 가상 머신으로 실행</a> 문서를 참고하여 Amazon Linux 2 가상 머신 이미지를 통해 온프레미스 개발 및 테스트를 위한 환경을 실행할 수 있다. 참고로 AL2을 대체하는 Amazon Linux 2023에 대해서는 <a href="https://github.com/amazonlinux/amazon-linux-2023/issues/102" target="_blank" rel="noreferrer">아직 가상 머신 이미지를 제공하지 않는</a> 것 같다. 그래서 AL2이 2025-06-30 일자로 EOL이 되더라도 VirtualBox에서 Amazon Linux 2를 실행해보고자 한다.</p><h4 id="amazon-linux-2-가상-머신-이미지-다운로드" tabindex="-1">Amazon Linux 2 가상 머신 이미지 다운로드 <a class="header-anchor" href="#amazon-linux-2-가상-머신-이미지-다운로드" aria-label="Permalink to “Amazon Linux 2 가상 머신 이미지 다운로드”">​</a></h4><p>우분투와 같이 Amazon Linux 2에 대한 설치 파일을 제공하는 것이 아니므로 부팅을 위한 이미지와 미리 정의된 가상 머신 이미지를 다운받아야 한다.</p><ul><li><a href="https://drive.google.com/file/d/17iBVLBLLJahQDb-3kgsWRCh72hzt1FIp/view?usp=sharing" target="_blank" rel="noreferrer">seed.iso 부팅 이미지</a></li><li><a href="https://cdn.amazonlinux.com/os-images/2.0.20230926.0/virtualbox/amzn2-virtualbox-2.0.20230926.0-x86_64.xfs.gpt.vdi" target="_blank" rel="noreferrer">Amazon Linux 2 LTS 2.0.20230926.0 x86_64 VirtualBox image</a></li></ul><h4 id="가상-머신-만들기-및-실행" tabindex="-1">가상 머신 만들기 및 실행 <a class="header-anchor" href="#가상-머신-만들기-및-실행" aria-label="Permalink to “가상 머신 만들기 및 실행”">​</a></h4><p><img src="/images/posts/amazonlinux2-virtualbox/01.png" alt="1. 가상 머신 만들기" loading="lazy"></p><p>새로 만들기 버튼을 눌러 가상 머신을 만듭니다. 리눅스 유형에 대한 운영 체제 종류는 공식 문서에 나와있는대로 Red Hat (64-bit)를 선택하자. 그리고 가상 디스크는 미리 정의된 가상 머신 이미지로 추가해야 한다. 위 스크린샷에 나와있는 듯이 <a href="https://cdn.amazonlinux.com/os-images/latest/" target="_blank" rel="noreferrer">Amazon Linux 2 가상 머신 이미지</a> 페이지에서 다운로드 받은 이미지를 선택하면 된다.</p><p><img src="/images/posts/amazonlinux2-virtualbox/02.png" alt="2. 부팅 이미지 디스크 추가" loading="lazy"></p><p>가상 머신을 실행하기 전에 호스트 이름과 사용자 계정 정의를 위한 부팅 이미지를 가상 광학 디스크에 추가해야한다. Amazon Linux 2 가상 머신 이미지 페이지에서 다운받을 수 있는 seed.iso 파일이 <code>VERR_NOT_SUPPORTED</code> 사유로 가상 광학 디스크에 추가할 수 없을 수 있는데 본 글에서 제공하는 seed.iso 부팅 이미지 링크를 통해 <code>기본 사용자(ec2-user:amazon)</code>만 정의된 파일을 다운로드할 수 있으니 참고하도록 하자.</p><p>※ 본 글에서 제공하는 seed.iso 파일은 아래와 같이 정의되어있다.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#cloud-config</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#vim:syntax=yaml</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">default</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">chpasswd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ec2-user:amazon</span></span></code></pre></div><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">local-hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">amazonlinux</span></span></code></pre></div><blockquote><p>부팅 이미지 파일은 MacOS 환경에서 hdiutil 도구를 사용하여 생성하였다. $ hdiutil makehybrid -o seed.iso -hfs -joliet -iso -default-volume-name cidata seedconfig/</p></blockquote><p><img src="/images/posts/amazonlinux2-virtualbox/03.png" alt="3. 사용자 계정 구성" loading="lazy"></p><p>가상 머신을 실행하고 맨처음 기본 사용자 계정인 ec2-user를 입력하면 사용자 계정에 대한 구성을 수행한다.</p><p><img src="/images/posts/amazonlinux2-virtualbox/04.png" alt="4. ec2-user 로그인" loading="lazy"></p><p>다시한번 로그인 화면이 출력되면 ec2-user와 amazon을 입력하면 위와 같이 Amazon Linux 2에 대한 로고를 확인할 수 있다. 처음 로그인에 성공했다면 그 이후에는 부팅 이미지가 필요하지 않다. 가상 머신을 종료하고 부팅 이미지를 가상 광학 디스크에서 제거하자.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};